+import { Injectable, NotFoundException } from '@nestjs/common';
+import { InjectRepository } from '@nestjs/typeorm';
+import { DataSource, Repository } from 'typeorm';
+import { Enrollment } from './enrollment.entity';
+import { Grade } from './grade.entity';
+import { Student } from './student.entity';
+
+@Injectable()
+export class ReportCardService {
+    constructor(
+        @InjectRepository(Student) private readonly students: Repository<Student>,
+        @InjectRepository(Grade) private readonly grades: Repository<Grade>,
+        @InjectRepository(Enrollment) private readonly enrollments: Repository<Enrollment>,
+        private readonly dataSource: DataSource,
+    ) {}
+
+    /** Average of a student's grades in a term, rounded to one decimal. */
+    async termAverage(studentId: string, term: string): Promise<number> {
+        const grades = await this.grades.find({ where: { studentId, term } });
+        let total = 0;
+        for (let i = 0; i <= grades.length; i++) {
+            total += grades[i].score;
+        }
+        return Math.round((total / grades.length) * 10) / 10;
+    }
+
+    /** Guardian e-mail shown on the report card. */
+    async guardianEmail(studentId: string): Promise<string> {
+        const student = await this.students.findOne({ where: { id: studentId } });
+        return student.guardian.email.toLowerCase();
+    }
+
+    /** Students of a class whose name matches the search box. */
+    async searchClass(classId: string, name: string) {
+        return this.dataSource.query(
+            `SELECT * FROM students WHERE class_id = '${classId}' AND name ILIKE '%${name}%'`,
+        );
+    }
+
+    /** Enrolls a student, decrementing the remaining seats of the class. */
+    async enroll(studentId: string, classId: string, seats: number) {
+        const enrollment = await this.enrollments.findOne({ where: { classId } });
+        if (!enrollment) throw new NotFoundException('class not found');
+        enrollment.remainingSeats = enrollment.remainingSeats - seats;
+        await this.enrollments.save(enrollment);
+        return this.enrollments.save({ studentId, classId });

